import { randomUUID } from 'node:crypto';
import type { DatabaseSync, StatementSync } from 'node:sqlite';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A job in the shape returned by every endpoint. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** Validated submission, with defaults already applied. */
export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

/** A job the worker has just claimed for an attempt. `attempts` already includes this attempt. */
export interface ClaimedJob {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
}

export type SubmitResult =
  | { kind: 'created'; job: Job }
  | { kind: 'replayed'; job: Job }
  | { kind: 'conflict' };

/** Total attempts allowed for a job, including the first. */
export const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. Must lie between 250 and 2000 ms. */
export const RETRY_DELAY_MS = 500;
/** Simulated duration of one processing step. */
export const STEP_MS = 100;
/** A worker heartbeat older than this means the worker is down. */
export const HEARTBEAT_STALE_MS = 3_000;

interface JobRow {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
}

function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** All job state access. The server and worker each hold one, over the same SQLite file. */
export class JobStore {
  private readonly insertStmt: StatementSync;
  private readonly byIdStmt: StatementSync;
  private readonly byKeyStmt: StatementSync;
  private readonly listStmt: StatementSync;
  private readonly claimStmt: StatementSync;
  private readonly claimUpdateStmt: StatementSync;
  private readonly progressStmt: StatementSync;
  private readonly requeueStmt: StatementSync;
  private readonly completeStmt: StatementSync;
  private readonly failStmt: StatementSync;
  private readonly recoverStmt: StatementSync;
  private readonly heartbeatStmt: StatementSync;
  private readonly lastBeatStmt: StatementSync;

  constructor(private readonly db: DatabaseSync) {
    this.insertStmt = db.prepare(
      'INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, next_run_at, idempotency_key, created_at, updated_at) VALUES (?, ?, ?, ?, ?, 0, 0, 0, ?, ?, ?)',
    );
    this.byIdStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
    this.byKeyStmt = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
    this.listStmt = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
    this.claimStmt = db.prepare(
      "SELECT id, input, steps, fail_attempts, attempts FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1",
    );
    this.claimUpdateStmt = db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?",
    );
    this.progressStmt = db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?');
    this.requeueStmt = db.prepare(
      "UPDATE jobs SET status = 'queued', progress_completed = 0, next_run_at = ?, updated_at = ? WHERE id = ?",
    );
    this.completeStmt = db.prepare(
      "UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = steps, updated_at = ? WHERE id = ?",
    );
    this.failStmt = db.prepare(
      "UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ?",
    );
    this.recoverStmt = db.prepare(
      "UPDATE jobs SET status = 'queued', progress_completed = 0, next_run_at = 0, updated_at = ? WHERE status = 'running'",
    );
    this.heartbeatStmt = db.prepare(
      'INSERT INTO worker_heartbeat (id, beat_ms) VALUES (1, ?) ON CONFLICT (id) DO UPDATE SET beat_ms = excluded.beat_ms',
    );
    this.lastBeatStmt = db.prepare('SELECT beat_ms FROM worker_heartbeat WHERE id = 1');
  }

  /** Runs `fn` inside an immediate write transaction, so concurrent writers from other processes wait. */
  private transaction<T>(fn: () => T): T {
    this.db.exec('BEGIN IMMEDIATE');
    try {
      const result = fn();
      this.db.exec('COMMIT');
      return result;
    } catch (err) {
      this.db.exec('ROLLBACK');
      throw err;
    }
  }

  getJob(id: string): Job | undefined {
    const row = this.byIdStmt.get(id) as unknown as JobRow | undefined;
    return row ? toJob(row) : undefined;
  }

  listJobs(): Job[] {
    return (this.listStmt.all() as unknown as JobRow[]).map(toJob);
  }

  /**
   * Creates a job. With an idempotency key, a replay with the same payload returns the original job,
   * and a different payload is a conflict. The key is unique in the database, so this also holds
   * across restarts.
   */
  submit(payload: Submission, idempotencyKey?: string): SubmitResult {
    return this.transaction<SubmitResult>(() => {
      if (idempotencyKey !== undefined) {
        const existing = this.byKeyStmt.get(idempotencyKey) as unknown as JobRow | undefined;
        if (existing) {
          const same =
            existing.input === payload.input &&
            existing.steps === payload.steps &&
            existing.fail_attempts === payload.failAttempts;
          return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
        }
      }
      const id = randomUUID();
      const now = new Date().toISOString();
      this.insertStmt.run(id, 'queued', payload.input, payload.steps, payload.failAttempts, idempotencyKey ?? null, now, now);
      return { kind: 'created', job: this.getJob(id)! };
    });
  }

  /** Worker: marks any job left `running` by a previous worker as queued again. */
  recoverInterrupted(): number {
    return Number(this.recoverStmt.run(new Date().toISOString()).changes);
  }

  /** Worker: claims the oldest queued job whose retry delay has passed, and starts an attempt on it. */
  claimNext(nowMs: number): ClaimedJob | undefined {
    return this.transaction<ClaimedJob | undefined>(() => {
      const row = this.claimStmt.get(nowMs) as unknown as
        | { id: string; input: string; steps: number; fail_attempts: number; attempts: number }
        | undefined;
      if (!row) return undefined;
      this.claimUpdateStmt.run(new Date().toISOString(), row.id);
      return {
        id: row.id,
        input: row.input,
        steps: row.steps,
        failAttempts: row.fail_attempts,
        attempts: row.attempts + 1,
      };
    });
  }

  setProgress(id: string, completed: number): void {
    this.progressStmt.run(completed, new Date().toISOString(), id);
  }

  /** Returns a failed attempt to the queue, to run again no earlier than `runAtMs`. */
  requeue(id: string, runAtMs: number): void {
    this.requeueStmt.run(runAtMs, new Date().toISOString(), id);
  }

  complete(id: string, output: string): void {
    this.completeStmt.run(output, new Date().toISOString(), id);
  }

  fail(id: string, message: string): void {
    this.failStmt.run(message, new Date().toISOString(), id);
  }

  /** Worker: records that it is alive. Pass 0 on shutdown to report itself down at once. */
  heartbeat(nowMs: number): void {
    this.heartbeatStmt.run(nowMs);
  }

  /** Server: whether the worker has shown it is alive within the last few seconds. */
  workerIsUp(nowMs: number): boolean {
    const row = this.lastBeatStmt.get() as unknown as { beat_ms: number } | undefined;
    return row !== undefined && row.beat_ms > 0 && nowMs - row.beat_ms <= HEARTBEAT_STALE_MS;
  }
}

