import type { Submission } from './jobs.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type ParseResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const INPUT_MAX_LENGTH = 1000;

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;

/** Checks the `Idempotency-Key` header. Returns the key, or a field error. */
export function parseIdempotencyKey(
  header: string | string[] | undefined,
): { ok: true; key: string | undefined } | { ok: false; fields: FieldError[] } {
  if (header === undefined) return { ok: true, key: undefined };
  if (typeof header === 'string' && IDEMPOTENCY_KEY_RE.test(header)) return { ok: true, key: header };
  return {
    ok: false,
    fields: [{ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' }],
  };
}

function isJsonContentType(contentType: string | undefined): boolean {
  const media = contentType?.split(';')[0]?.trim().toLowerCase();
  return media === 'application/json';
}

function integerField(
  body: Record<string, unknown>,
  name: 'steps' | 'failAttempts',
  min: number,
  max: number,
  fallback: number,
  fields: FieldError[],
): number {
  const value = body[name];
  if (value === undefined) return fallback;
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return value;
}

/** Validates a job submission body. Collects every offending field rather than stopping at the first. */
export function parseSubmission(contentType: string | undefined, rawBody: string): ParseResult {
  if (!isJsonContentType(contentType)) {
    return { ok: false, fields: [{ field: 'body', message: 'Content-Type must be application/json' }] };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    return { ok: false, fields: [{ field: 'body', message: 'body is not valid JSON' }] };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return { ok: false, fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  }
  const body = parsed as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(body)) {
    if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  const rawInput = body.input;
  if (rawInput === undefined) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof rawInput !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (rawInput.length < 1 || rawInput.length > INPUT_MAX_LENGTH) {
    fields.push({ field: 'input', message: `must be 1 to ${INPUT_MAX_LENGTH} characters` });
  } else if (rawInput.trim().length === 0) {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = rawInput;
  }

  const steps = integerField(body, 'steps', 1, 20, DEFAULT_STEPS, fields);
  const failAttempts = integerField(body, 'failAttempts', 0, 5, DEFAULT_FAIL_ATTEMPTS, fields);

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

