import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { JobStore, type Job } from './jobs.ts';
import { parseIdempotencyKey, parseSubmission, type FieldError } from './validation.ts';

/** Generous limit: the largest valid submission is about 4 KB of UTF-8 plus JSON syntax. */
const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const store = new JobStore(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function sendInvalid(res: ServerResponse, fields: FieldError[]): void {
  const summary = fields.map((f) => f.field).join(', ');
  sendError(res, 400, 'invalid_request', `Invalid request: ${summary}.`, fields);
}

function jobJson(job: Job) {
  return job;
}

/** Reads the request body as UTF-8. Resolves to null if it exceeds the size limit. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawBody = await readBody(req);
  const key = parseIdempotencyKey(req.headers['idempotency-key']);
  const body =
    rawBody === null
      ? { ok: false as const, fields: [{ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` }] }
      : parseSubmission(req.headers['content-type'], rawBody);

  const fields: FieldError[] = [...(key.ok ? [] : key.fields), ...(body.ok ? [] : body.fields)];
  if (fields.length > 0 || !key.ok || !body.ok) {
    sendInvalid(res, fields);
    return;
  }

  const result = store.submit(body.value, key.key);
  if (result.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, result.kind === 'created' ? 201 : 200, jobJson(result.job));
}

function handle(req: IncomingMessage, res: ServerResponse): void {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  const allow = (methods: string[]): boolean => {
    if (methods.includes(method)) return true;
    res.setHeader('allow', methods.join(', '));
    sendError(res, 405, 'method_not_allowed', `${method} is not allowed on ${pathname}.`);
    return false;
  };

  if (pathname === '/health') {
    if (!allow(['GET'])) return;
    send(res, 200, { status: 'ok', worker: store.workerIsUp(Date.now()) ? 'up' : 'down' });
    return;
  }

  if (pathname === '/') {
    if (!allow(['GET'])) return;
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (!allow(['GET', 'POST'])) return;
    if (method === 'POST') {
      void createJob(req, res).catch((err: unknown) => {
        console.error('create job failed:', err);
        if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error.');
      });
      return;
    }
    send(res, 200, { jobs: store.listJobs().map(jobJson) });
    return;
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (!allow(['GET'])) return;
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      sendError(res, 404, 'not_found', 'No such job.');
      return;
    }
    const job = store.getJob(id);
    if (!job) {
      sendError(res, 404, 'not_found', `No job with id ${id}.`);
      return;
    }
    send(res, 200, jobJson(job));
    return;
  }

  sendError(res, 404, 'not_found', `No route for ${pathname}.`);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  try {
    handle(req, res);
  } catch (err) {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error.');
  }
});

server.listen(port, () => console.log(`server listening on ${port}`));

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  setTimeout(() => process.exit(0), 3_000).unref();
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

