import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { JobStore, MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, type ClaimedJob } from './jobs.ts';

const HEARTBEAT_INTERVAL_MS = 500;
const IDLE_POLL_MS = 200;

const db = openDatabase();
const store = new JobStore(db);
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Runs one attempt. A job still `running` when the worker stops is recovered on the next start. */
async function runAttempt(job: ClaimedJob): Promise<void> {
  // Simulated transient failure: attempt n fails before any progress when n <= failAttempts.
  if (job.attempts <= job.failAttempts) {
    if (job.attempts >= MAX_ATTEMPTS) store.fail(job.id, 'transient failure');
    else store.requeue(job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let done = 1; done <= job.steps; done++) {
    if (stopping) return;
    await sleep(STEP_MS);
    store.setProgress(job.id, done);
  }
  store.complete(job.id, job.input.toUpperCase());
}

// Jobs left running by a previous worker are picked up again, so recovery has to happen before the loop starts.
const recovered = store.recoverInterrupted();
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);

store.heartbeat(Date.now());
const heartbeat = setInterval(() => store.heartbeat(Date.now()), HEARTBEAT_INTERVAL_MS);

console.log('worker started');
while (!stopping) {
  const job = store.claimNext(Date.now());
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  await runAttempt(job);
}

clearInterval(heartbeat);
store.heartbeat(0);
db.close();
console.log('worker stopped');

